 910	\subsubsection{Generating new measurements}
 911	
 912	In this section, we show how to combine multiple measurements into a single measurement by ``sandwiching" them together.
 913	
 914	\begin{fact}\label{fact:sandwich}
 915	Let $k \geq 0$ be a constant.
 916	Let $\{A^x_{a_1, \ldots, a_k}\}$ be a projective measurement.
 917	For each $1 \leq i \leq k$, let $\{(B_i)^x_{a_i}\}$ be a projective measurement, and suppose that
 918	\begin{equation}\label{eq:no-take-only-throw}
 919	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 920	\end{equation}
 921	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
 922	\begin{equation*}
 923	J^x_{a_1, \ldots, a_k} := (B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k}.
 924	\end{equation*}
 925	Then
 926	\begin{equation*}
 927	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta^{1/2}} I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 928	\end{equation*}
 929	\end{fact}
 930	\begin{proof}
 931	For each $1 \leq i \leq k$, 
 932	\Cref{eq:no-take-only-throw} implies that
 933	\begin{equation*}
 934	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 935	\end{equation*}
 936	Now, we repeatedly apply this using \Cref{fact:add-a-proj}:
 937	\begin{align*}
 938	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
 939	& = (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k}})_{\reg{Alice}} \otimes I_{\reg{Bob}}\\
 940	& \approx_{\delta} (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k-1}})_{\reg{Alice}} \otimes ((B_k)^x_{a_k})_{\reg{Bob}}\\
 941	&\qquad\qquad\qquad \qquad \qquad \qquad \cdots\\
 942	& \approx_{\delta} I_{\reg{Alice}} \otimes ((B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k})_{\reg{Bob}}\\
 943	& = I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 944	\end{align*}
 945	The fact now follows from \Cref{fact:almost-agreement} and the fact that~$A$ is a projective measurement.
 946	\end{proof}
 947	
 948	Next, we extend \Cref{fact:sandwich} to the case of polynomial measurements (see \Cref{sec:classical-q-low-deg} below).
 949	These are structured measurements in which the prover returns the evaluation of a function sampled independently from their input.
 950	The goal is to retain this structure even after ``sandwiching" them together.
 951	
 952	\begin{fact}\label{fact:low-degree-sandwich}
 953	Let $k \geq 0$ be a constant.
 954	Let $\calD$ be a distribution on questions $x \in \calX$.
 955	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calX \rightarrow \calR_i$.
 956	and let $\{G^i_g\}$ be a projective measurement with outcomes from this set.
 957	Suppose that the set $\calG_i$ has the following distance property:
 958	for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\bx) = g_i'(\bx)$, over a random $\bx \sim \calD$, is at most $\eps$.
 959	
 960	Let $\{A_{g_1, \ldots, g_k}\}$ be a projective measurement with outcomes $g_i \in \calF_i$.
 961	For each $1 \leq i \leq k$, suppose that
 962	\begin{equation}\label{eq:treat-yo-self}
 963	(A_{[g_i(x) = a_i]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes (G^i_{[g_i(x)=a_i]})_{\reg{Bob}}.
 964	\end{equation}
 965	Define the POVM measurement $\{J_{g_1, \ldots, g_k}\}$ as
 966	\begin{equation*}
 967	J_{g_1, \ldots, g_k} := G^k_{g_k} \cdots G^2_{g_2} \cdot G^1_{g_1} \cdot G^2_{g_2} \cdots G^k_{g_k}.
 968	\end{equation*}
 969	Then
 970	\begin{equation*}
 971	(A_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Bob}}.
 972	\end{equation*}
 973	\end{fact}
 974	\begin{proof}
 975	Let $1 \leq i \leq k$.
 976	By~\Cref{eq:treat-yo-self},
 977	if Alice measures with~$A$, producing~$\bg_i$, and Bob measures with~$G^i$, producing~$\bg_i'$,
 978	then the probability that $\bg_i(\bx) \neq \bg_i'(\bx)$ is $O(\delta)$.
 979	Write $\eta$ for the probability that $\bg_i \neq \bg_i'$.
 980	Then we have the expression $\eta \cdot (1-\eps) \leq O(\delta)$ or, equivalently, $\eta \leq O(\delta/(1-\eps))$.
 981	When $\eps < 1/2$, this gives the bound $\eta \leq O(\delta)$, and when $\eps \geq 1/2$, we have the trivial bound $\eta \leq O(\eps)$.
 982	As a result, $\eta = O(\delta + \eps)$.
 983	
 984	In conclusion,
 985	\begin{equation*}
 986	(A_{g_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta + \eps} I_{\reg{Alice}} \otimes (G^i_{g_i})_{\reg{Bob}}.
 987	\end{equation*}
 988	We can now apply \Cref{fact:sandwich} to $A_{g_1, \ldots, g_k}$ and the $G^i_{g_i}$ measurements.
 989	It implies that
 990	\begin{equation*}
 991	(A_{g_1, \ldots, g_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{g_1, \ldots, g_k})_{\reg{Bob}}.
 992	\end{equation*}
 993	The fact now follows from the data processing inequality \Cref{fact:specialize-the-simeq}.
 994	\end{proof}
 995	
 996	In our next fact, we show that \Cref{fact:low-degree-sandwich} holds even when we drop the structured assumption on the~$A$ matrix.
 997	The tradeoff is that we must now assume that the~$k$ different measurements act on different parts of the input string.
 998	In this case, the distance condition becomes slightly more cumbersome to state.
 999	
1000	\begin{fact}\label{fact:low-degree-sandwich-on-steroids}
1001	Let $k \geq 0$ be a constant.
1002	Let $\calD$ be a distribution on questions $(x, y_1, \ldots, y_k)$, where each $y_i \in \calY_i$.
1003	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calY_i \rightarrow \calR_i$.
1004	and let $\{(G_i)^x_g\}$ be a projective measurement with outcomes from this set.
1005	(For the $i=1$ case, we also allow this measurement to be a POVM.)
1006	Suppose that the set $\calG_i$ has the following distance property:
1007	fix a question $z = (x, y_1, \ldots, y_{i-1}, y_{i+1}, \ldots, y_k)$, and let $\calD_z$ be the distribution on~$y_i$ conditioned on the other outcomes~$z$.
1008	Then for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\by_i) = g_i'(\by_i)$, over a random $\by_i \sim \calD_z$, is at most $\eps$.
1009	
1010	Let $\{A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k} \}$ be a projective measurement with outcomes $g_i \in \calF_i$.
1011	For each $1 \leq i \leq k$, suppose that
1012	\begin{equation}\label{eq:gonna-compare-like-a-pear}
1013	(A^{x, y_1, \ldots, y_k}_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((G_i)^x_{[g_i(y_i)=a_i]})_{\reg{Bob}}.
1014	\end{equation}
1015	Suppose also that
1016	\begin{equation}\label{eq:spend-some-time-reflecting}
1017	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1018		\simeq_{\delta} I_{\reg{Alice}} \otimes (A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Bob}}.
1019	\end{equation}
1020	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
1021	\begin{equation*}
1022	J^x_{g_1, \ldots, g_k} := (G_k)^x_{g_k} \cdots (G_2)^x_{g_2} \cdot (G_1)^x_{g_1} \cdot (G_2)^x_{g_2} \cdots (G_k)^x_{g_k}.
1023	\end{equation*}
1024	Then
1025	\begin{equation*}
1026	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1027		\simeq_{\poly(\delta, \eps)} I_{\reg{Alice}} \otimes (J^x_{[g_1(y_1), \ldots, g_k(y_k) = a_1, \ldots, a_k]})_{\reg{Bob}}.
1028	\end{equation*}
1029	\end{fact}
1030	\begin{proof}
1031	First, we show how to reduce this to the $k = 2$ case. Then we prove it for that case.
1032	Assume the fact holds when $k = 2$.  Define the POVM measurement $\{(J_i)^x_{g_1, \ldots, g_i}\}$ as
1033	\begin{equation*}
1034	(J_i)^x_{g_1, \ldots, g_i} := (G_i)^x_{g_i} \cdots (G_2)^x_{g_2} \cdot (G_1)^x_{g_1} \cdot (G_2)^x_{g_2} \cdots (G_i)^x_{g_i}.
1035	\end{equation*}
1036	We will show by induction that 
1037	\begin{equation}\label{eq:hi-i-work-in-graphics-but-not-that-graphics}
1038	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1039		\simeq_{\poly(\delta, \eps)} I_{\reg{Alice}} \otimes ((J_i)^x_{[g_1(y_1), \ldots, g_i(y_i) = a_1, \ldots, a_i]})_{\reg{Bob}},
1040	\end{equation}
1041	the base case being trivial. Assume this holds for~$i$.
1042	We apply the $k = 2$ case as follows:
1043	consider the question tuple $(y_1, \ldots, y_i)$ as a single question
1044	and consider functions of the form $(y_1, \ldots, y_i) \mapsto (g_1(y_1), \ldots, g_i(y_i))$.
1045	Then the first POVM measurement is $J_i$, which satisfies \Cref{eq:gonna-compare-like-a-pear} due to \Cref{eq:hi-i-work-in-graphics-but-not-that-graphics}.
1046	The second measurement is the projector $G_{i+1}$.
1047	Then the $k = 2$ case immediately implies the $i+1$ case of \Cref{eq:hi-i-work-in-graphics-but-not-that-graphics}.
1048	
1049	Now we prove the $k = 2$ case.
1050	Our goal is to show that
1051	\begin{equation}\label{eq:food-rakes}
1052	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1053	\otimes ((G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2})_{\reg{Bob}} \ket{\psi}
1054	\end{equation}
1055	is at least $1- \poly(\delta, \eps)$.
1056	We will do this by showing that
1057	\begin{equation}\label{eq:what-a-johnnie-wants}
1058	((G_1)^x_{[g_1(y_1)=a_1]} \cdot (G_2)^x_{g_2})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1059	\approx_{\poly(\delta, \eps)} ((G_2)^x_{g_2} \cdot (G_1)^x_{[g_1(y_1)=a_1]})_{\reg{Alice}} \otimes I_{\reg{Bob}}.
1060	\end{equation}
1061	is at most $\poly(\delta, \eps)$.
1062	To see that this is sufficient, note that the related expression
1063	\begin{equation*}
1064	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1065	\otimes ((G_2)^{\bx}_{g_2} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]})_{\reg{Bob}} \ket{\psi}
1066	\end{equation*}
1067	is exactly equal to~$1$ because $G_2$ is a projector.
1068	Taking the difference between this and \Cref{eq:food-rakes}, we get
1069	\begin{equation*}
1070	\E_{\bx, \by_1, \by_2} \sum_{a_1, g_2} \bra{\psi} (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}}
1071	\otimes ((G_2)^{\bx}_{g_2} \cdot ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2}- (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]}))_{\reg{Bob}} \ket{\psi}.
1072	\end{equation*}
1073	Cauchy-Schwarz allows us to bound this by
1074	\begin{multline*}
1075	\leq \E_{\bx, \by_1, \by_2} \sqrt{ \sum_{a_1, g_2}\Vert (A^{\bx, \by_1, \by_2}_{a_1, g_2(\by_2)})_{\reg{Alice}} \otimes ((G_2)^{\bx}_{g_2})_{\reg{Bob}} \ket{\psi} \Vert^2}\\
1076		\cdot \sqrt{ \sum_{a_1, g_2}\Vert I_{\reg{Alice}} \otimes ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2}- (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]})_{\reg{Bob}} \ket{\psi} \Vert^2}.
1077	\end{multline*}
1078	The expression inside the first square root is always at most~$1$.
1079	This allows us to bring the expectation into the second square root by Jensen's inequality,
1080	and the resulting expression we can bound due to \Cref{eq:what-a-johnnie-wants}.
1390	\begin{proof}
1391	Suppose the verifier (i)  samples $(\bs, \bu) \sim \calD$,
1392	(ii) gives Alice~$\bs$, who measures with $M^{\bs}$ and returns her outcome~$\boldf : \bs \rightarrow \F_q$,
1393	(iii) receives~$\bg : \F_q^m \rightarrow \F_q$ from Bob, sampled via~$G$,
1394	and (iv) accepts if $\boldf(\bu) = \bg(\bu)$.
1395	Then by assumption, the verifier accepts with probability at least $1-O(\delta)$.
1396	
1397	We can use this to bound the probability that $\boldf$ and $\bg$ disagree on the subspace~$\bs$.
1398	By Schwartz-Zippel (\Cref{lem:schwartz-zippel}), conditioned on $\boldf$ and $\bg$ disagreeing,
1399	the probability they disagree on a random point $\bu \sim \bs$  is at least $1-d/q$.
1400	This gives us the inequality $\Pr[\boldf \neq \bg|_{\bs}] \cdot (1-d/q) \leq O(\delta)$.
1401	Now, assume first that $q \geq 2d$. Then this bound implies, via \Cref{fact:agreement}, that
1402	\begin{equation}\label{eq:almost-there-almost-there}
1403	M^s_f \otimes I_{\reg{Bob}} \approx_{\delta + d/q} I_{\reg{Alice}} \otimes G_{[g|_{s} = f]}.
1404	\end{equation}
1405	On the other hand, when $q \geq 2d$, then this bound is also true for trivial reasons.
1406	This is because we can pick $\delta(\cdot)$ such that $\delta(\eps) \geq 1$ in this case.
1407	\end{proof}
1408	
1409	\subsection{Quantum soundness of the classical simultaneous low-degree test}\label{sec:q-simultaneous}
1410	
1411	We would now like to use \Cref{thm:anand-thomas-classical-low-degree}
1412	to show quantum soundness for the simultaneous classical low-degree test.
1413	This will be done using the same reduction presented in~\Cref{sec:simultaneous-classical}.
1414	The main result is the following.
1415	
1416	\begin{theorem}[Quantum soundness of the simultaneous classical
1417	  low-degree test]
1418	  \label{thm:simultaneous-ldt}
1419	There exists a constant $c > 0$ and a function $\delta(\eps) = \mathrm{poly}(\epsilon, d (m + \ell)/q^c)$ such that the following holds.
1420	Suppose Alice and Bob are entangled provers who pass $\game_{\mathrm{Surface}}^\ell(m,d,q,2)$ with probability at least $1-\eps$
1421	using the strategy $(\psi, M)$, where~$M$ consists of projective measurements.
1422	Then there exists a measurement $G \in \simulpolymeas{m}{d}{q}{\ell}$ such that
1423	\begin{equation*}
1424	M^w_{b_1, \ldots, b_\ell} \otimes I_{\reg{Bob}} \consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes G_{[g_1(w), \ldots, g_\ell(w) = b_1, \ldots, b_\ell]},
1425	\qquad
1426	G_{g_1, \ldots, g_\ell} \otimes I_{\reg{Bob}}
1427	\consistency_{\delta(\eps)}
1428	I_{\reg{Alice}} \otimes G_{g_1, \ldots, g_\ell},
1429	\end{equation*}
1430	where the first is on the uniform distribution over $\F_q^m$.
1431	\end{theorem}
1432	
1433	\begin{proof}
1434	Suppose Alice and Bob pass $\game_{\mathrm{Surface}}^\ell(m, d, q,2)$ with probability at least $1-\eps$.
1435	We will use them to simulate two provers, ``Combined Alice" and ``Combined Bob", who pass
1436	the single-function low-degree test $\game_{\mathrm{Surface}}(\ell + m, d+1, q,2)$ with probability at least $1-\eps$.
1437	They are specified as follows:
1438	\begin{itemize}
1439	\item[$\circ$] \textbf{Combined Alice:} Given $\bs \subseteq \F_q^{\ell + m}$, draw $\bs' \sim_2 \bs_{\mathrm{proj}}$.  Give it to Alice, who responds with $\boldf_1, \ldots, \boldf_{\ell}: \bs' \rightarrow \F_q$.  Output the function $\mathrm{combine}_{\boldf}|_{\bs}$.
1440	\item[$\circ$] \textbf{Combined Bob:} Given $(\bx, \by) \in \F_q^{\ell + m}$, compute $\by \in \F_q^m$. Give it to Bob, who responds with $\bb_1, \ldots, \bb_\ell \in \F_q$.
1441				Return $\mathrm{combine}_{\bb}(\bx) \in \F_q$.
1442	\end{itemize}
1443	By \Cref{prop:really-the-same-dist}, $\bs'$ and $\by$ are distributed as the questions in $\game_{\mathrm{Surface}}^\ell(m, d, q,2)$.
1444	Using our assumption on Alice and Bob, this means that $\boldf_1(\by) = \bb_1$, \ldots, $\boldf_\ell(\by) = \bb_\ell$ with probability at least $1-\eps$.
1445	As a result, $(\mathrm{combine}_{\boldf}|_{\bs})(\bx, \by) = \mathrm{combine}_{\bb}(\by)$ with probability at least~$1-\eps$.
1446	By \Cref{prop:sub-subspace}, $\mathrm{combine}_{\boldf}|_{\bs}$ is a degree-$(d+1)$ function on~$\bs$,
1447	and so it is a valid response to subspace queries.
1448	This means Combined Alice and Bob pass~$\game_{\mathrm{Surface}}(\ell + m, d+1, q, 2)$ with probability at least~$1-\eps$.
1449	
1450	Thus, we can apply \Cref{thm:anand-thomas-classical-low-degree}.
1451	It gives a measurement $G \in \polymeas{\ell+m}{d+1}{q}$ such that
1452	\begin{equation}\label{eq:g-meas-equals-combine-meas}
1453	M^y_{[\mathrm{combine}_b(x)=\nu]} \otimes I_{\reg{Bob}}
1454	\consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes G_{[g(x, y) = \nu]},
1455	\qquad
1456	G_g \otimes I_{\reg{Bob}} \consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes G_g,
1457	\end{equation}
1458	where $\delta(\eps) = \poly(\eps, (d+1)(\ell+m)/q^c)$.
1459	This means that if we give Alice~$\by$ and she returns~$\bb$, and Bob simply returns~$\bg$,
1460	then $\mathrm{combine}_{\bb}(\bx) = g(\bx, \by)$ with probability at least~$1-\delta(\eps)$.
1461	
1462	We would like to show that~$\bg$ is exactly linear in~$x$ with high probability, over the randomness in the measurement~$G$.
1463	Let us condition on a $\bg$ which is not exactly linear.
1464	By \Cref{prop:exactly-linear-prop}, the probability that $\bg|_{\by}$ is not exactly linear is at least $1-(d+1)/q$.
1465	On the other hand, because $\mathrm{combine}_{\bb}(\bx)$ is always exactly linear by construction,
1466	the probability that $\bg|_{\by}(\bx) = \mathrm{combine}_{\bb}(\bx)$ is at most $(d+1)/q$ by Schwartz-Zippel (\Cref{lem:schwartz-zippel}).
1467	As a result, the probability that $\bg(\bx, \by) = \mathrm{combine}_{\bb}(\bx)$ is at most $(d+1)/q + (d+1)/q$.
1468	Thus, if we write $\mu_{\mathrm{linear}}$ for the probability that $\bg$ is exactly linear, we have equality at most $\mu_{\mathrm{linear}} + 2(d+1)/q$ fraction of the time.
1469	Rearranging, $\bg$ is exactly linear with probability
1470	\begin{equation*}
1471	\mu_{\mathrm{linear}} \geq 1 - 2\delta(\eps) - 2(d+1)/q.
1472	\end{equation*}
1473	Define a new measurement $\{H_{g_1, \ldots, g_\ell}\} \in \simulpolymeas{m}{d}{q}{\ell}$ operationally as follows: first, measure~$G$ and receive~$\bg$.
1474	If it is exactly linear, it can be written as $\sum_i x_i \cdot \bg_i(y)$, and so output $\bg_1, \ldots, \bg_\ell$.
1475	If~$\bg$ is \emph{not} exactly linear, output any arbitrary degree-$d$ polynomials instead.
1476	When~$\bg$ is exactly linear, we have $\mathrm{combine}_{\bg_1, \ldots, \bg_\ell}(x, y) = \bg(x, y)$.
1477	Since this happens with probability at least $1-\delta(\eps)$,
1478	we can replace~$G$ with~$H$ in \Cref{eq:g-meas-equals-combine-meas}, yielding
1479	\begin{equation}\label{eq:no-name-is-a-bad-name}
1480	M^y_{[\mathrm{combine}_b(x)=\nu]} \otimes I_{\reg{Bob}}
1481	\consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes H_{[\mathrm{combine}_g(x, y) = \nu]},
1482	\end{equation}
1483	On the other hand, because~$H$ is just~$G$ with data processing applied to its output,
1484	we can apply \Cref{fact:specialize-the-simeq} to \Cref{eq:g-meas-equals-combine-meas}. This produces the equation
1485	\begin{equation*}
1486	H_{g_1, \ldots, g_\ell} \otimes I_{\reg{Bob}} \consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes H_{g_1, \ldots, g_\ell}.
1487	\end{equation*}
1488	
1489	Consider $\bg_1, \ldots, \bg_\ell$ drawn by Bob using~$H$.
1490	For any fixed~$b$ and~$y$, if it is not the case that $g_1(y) = b_1$, \ldots, $g_\ell(y) = b_\ell$,
1491	then the probability that $\mathrm{combine}_{\bg}(\bx, y) = \mathrm{combine}_{b}(\bx)$
1492	over a random~$\bx$ is at most $1/q$ by Schwartz-Zippel, since both are exactly linear functions.
1493	Thus, if Alice draws~$\bb_1, \ldots, \bb_\ell$ given~$\by$,
1494	and we write~$\eta$ for the probability that $\bg_1(\by) = \bb_1$, \ldots, $\bg_\ell(\by) = \bb_\ell$,
1495	then the probability that $\mathrm{combine}_{\bg}(\bx, \by) = \mathrm{combine}_{\bb}(\bx)$ is at most
1496	$\eta +  (1-\eta) \cdot 1/q$.
1497	Combined with \Cref{eq:no-name-is-a-bad-name}, this implies that
1498	\begin{equation*}
1499	\Pr[\bg_1(\by) = \bb_1, \ldots, \bg_\ell(\by) = \bb_\ell] \geq 1- \delta(\eps) - 1/q.
1500	\end{equation*}
1501	Or, equivalently,
1502	\begin{equation*}
1503	M^y_{b_1, \ldots, b_\ell} \otimes I_{\reg{Bob}}
1504	\consistency_{\delta(\eps)} I_{\reg{Alice}} \otimes G_{[g_1(y), \ldots, g_\ell(y) = b_1, \ldots, b_\ell]}.\qedhere
1505	\end{equation*}
1506	\end{proof}
1507	
1508	\subsection{Self-testing}
1509	
1510	The games presented in \Cref{sec:classical-q-low-deg,sec:q-simultaneous} might be referred to as ``measurement testers":
1511	if a strategy passes them with high probability, then we can extract some property on its measurements.
1512	In this section, we will introduce a significantly stronger notion of testing called \emph{self-testing}.
1513	A self-tester is a game in which if a prover passes with high probability,
1514	then not only do we do exactly which measurements the prover must be performing,
1515	we also know which exactly state it must be performing them on (up to local isometry).
1516	(We note that some works use ``self-testing" to refer both to ``measurement testing" and what we refer to as ``self-testing"~\cite{NV18a}.
1517	In this work, we will reserve the term exclusively for the latter.) We begin with a definition.
1518	
1519	\begin{definition}
1520	We say that $\mathcal{S} = (\psi, M)$ is a \emph{partial strategy} for $\game$
1521	if $M$ contains the POVM $M^x$ for only a subset of the questions in~$\game$.
1522	We call this set of questions $\mathcal{S}$'s \emph{question set}.
1523	A strategy $\mathcal{S}' = (\psi, M')$ \emph{extends} $\mathcal{S}$ if $(M')^x = M^x$ for every~$x$ in $\mathcal{S}$'s question set.
1524	\end{definition}
